CREATE TRIGGER RefCusProcedure_Version_Create
	ON RefCusProcedure
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT ZZ6_PK, 'ZZ6'
	FROM inserted
GO
CREATE TRIGGER RefCusProcedure_Version_Update
	ON RefCusProcedure
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON ZZ6_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
